/// CERT_LIMIT
pub fn cert_limit(num_players: u8) -> u8 {
    match num_players {
        2 => 27,
        3 => 16,
        4 => 13,
        5 => 10,
        _ => panic!("1822MX: invalid player count {num_players}"),
    }
}

/// STARTING_CASH
pub fn starting_cash(num_players: u8) -> i32 {
    match num_players {
        2 => 750,
        3 => 500,
        4 => 375,
        5 => 300,
        _ => panic!("1822MX: invalid player count {num_players}"),
    }
}

/// BIDDING_TOKENS (keyed by player count)
pub fn bidding_tokens(players: usize) -> i32 {
    match players {
        2 => 7,
        3 => 6,
        4 => 5,
        5 => 4,
        _ => 0,
    }
}

